def compute(vars):
    net_change = vars["v1"] - vars["v2"]
    return {
        "value": net_change,
        "trace": {
            "net_revenue_2004": vars["v1"],
            "net_revenue_2003": vars["v2"],
            "net_change": net_change,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": None
            }
        }
    }
